"""Concentration principle: optimal radial placement of a fixed area budget.

Given a fixed total collecting area and an admissible radial band
[R_min, R_max], the captured power is maximized by placing all area at R_min,
because solid angle per unit area 1/R^2 decreases with radius.
"""
from __future__ import annotations
import math

FOUR_PI = 4.0 * math.pi

def captured_power(L: float, R: float, area: float) -> float:
    return area * L / (FOUR_PI * R ** 2)

def optimal_placement(L: float, area_budget: float, r_min: float, r_max: float) -> dict:
    best = captured_power(L, r_min, area_budget)
    worst = captured_power(L, r_max, area_budget)
    return {"best_radius": r_min, "best_power": best,
            "worst_radius": r_max, "worst_power": worst,
            "gain_ratio": best / worst}

if __name__ == "__main__":
    L, AU = 3.828e26, 1.496e11
    print(optimal_placement(L, 1e18, 0.3 * AU, 5.0 * AU))
